17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
37	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
38	import org.springframework.samples.petclinic.rest.controller.RequiredFieldsMissingException;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper) {
75	        this.clinicService = clinicService;
76	        this.ownerMapper = ownerMapper;
77	        this.petMapper = petMapper;
78	        this.visitMapper = visitMapper;
79	    }
80	
81	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
82	    @Override
83	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
84	        Collection<Owner> owners;
85	        if (lastName != null) {
86	            owners = this.clinicService.findOwnerByLastName(lastName);
87	        } else {
88	            owners = this.clinicService.findAllOwners();
89	        }
90	        if (owners.isEmpty()) {
91	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
92	        }
93	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
99	        Owner owner = this.clinicService.findOwnerById(ownerId);
100	        if (owner == null) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
109	        validateRequiredFields(ownerFieldsDto);
110	        normalizeTelephone(ownerFieldsDto);
111	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
112	        normalizeEmail(ownerFieldsDto);
113	        defaultRegistrationDate(ownerFieldsDto);
114	        HttpHeaders headers = new HttpHeaders();
115	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
116	        this.clinicService.saveOwner(owner);
117	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
118	        headers.setLocation(UriComponentsBuilder.newInstance()
119	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
120	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
126	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
127	        if (currentOwner == null) {
128	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
129	        }
130	        normalizeEmail(ownerFieldsDto);
131	        currentOwner.setAddress(ownerFieldsDto.getAddress());
132	        currentOwner.setCity(ownerFieldsDto.getCity());
133	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
134	        currentOwner.setLastName(ownerFieldsDto.getLastName());
135	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
136	        currentOwner.setEmail(ownerFieldsDto.getEmail());
137	        this.clinicService.saveOwner(currentOwner);
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Transactional
143	    @Override
144	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
145	        Owner owner = this.clinicService.findOwnerById(ownerId);
146	        if (owner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        this.clinicService.deleteOwner(owner);
150	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
156	        Owner owner = this.clinicService.findOwnerById(ownerId);
157	        if (owner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        HttpHeaders headers = new HttpHeaders();
161	        Pet pet = petMapper.toPet(petFieldsDto);
162	        owner.setId(ownerId);
163	        pet.setOwner(owner);
164	        pet.getType().setName(null);
165	        this.clinicService.savePet(pet);
166	        PetDto petDto = petMapper.toPetDto(pet);
167	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
168	            .buildAndExpand(pet.getId()).toUri());
169	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
175	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
176	        if (currentOwner != null) {
177	            Pet currentPet = this.clinicService.findPetById(petId);
178	            if (currentPet != null) {
179	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
180	                currentPet.setName(petFieldsDto.getName());
181	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
182	                this.clinicService.savePet(currentPet);
183	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
184	            }
185	        }
186	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
192	        HttpHeaders headers = new HttpHeaders();
193	        Visit visit = visitMapper.toVisit(visitFieldsDto);
194	        Pet pet = new Pet();
195	        pet.setId(petId);
196	        visit.setPet(pet);
197	        this.clinicService.saveVisit(visit);
198	        VisitDto visitDto = visitMapper.toVisitDto(visit);
199	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
200	            .buildAndExpand(visit.getId()).toUri());
201	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
202	    }
203	
204	
205	    /**
206	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
207	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
208	     * Validation already rejects {@code null} values and the pattern-constrained fields
209	     * when blank, but {@code address} and {@code city} have no pattern, so a
210	     * whitespace-only value would otherwise slip through.
211	     *
212	     * @param ownerFieldsDto the submitted owner fields
213	     * @throws RequiredFieldsMissingException if any required field is missing or blank
214	     */
215	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
216	        List<String> errors = new ArrayList<>();
217	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
218	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
219	        requireText("address", ownerFieldsDto.getAddress(), errors);
220	        requireText("city", ownerFieldsDto.getCity(), errors);
221	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
222	        if (!errors.isEmpty()) {
223	            throw new RequiredFieldsMissingException(errors);
224	        }
225	    }
226	
227	    private static void requireText(String field, String value, List<String> errors) {
228	        if (value == null || value.isBlank()) {
229	            errors.add(field);
230	        }
231	    }
232	
233	    /**
234	     * Normalizes the submitted telephone on create by stripping every non-digit character,
235	     * then requires the result to contain exactly 10 digits. The stripped, 10-digit value is
236	     * written back onto the request so it is persisted and echoed back verbatim.
237	     *
238	     * @param ownerFieldsDto the submitted owner fields
239	     * @throws RequiredFieldsMissingException with a 400 status if the telephone does not
240	     *                                        contain exactly 10 digits once stripped
241	     */
242	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
243	        String telephone = ownerFieldsDto.getTelephone();
244	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
245	        if (digits.length() != 10) {
246	            throw new RequiredFieldsMissingException(List.of("telephone"));
247	        }
248	        ownerFieldsDto.setTelephone(digits);
249	    }
250	
251	    /**
252	     * Rejects a create whose normalized telephone is already used by any existing owner.
253	     * The submitted telephone has already been normalized to its bare digits by
254	     * {@link #normalizeTelephone}; each stored owner's telephone is normalized the same way
255	     * before comparison so differing input formats collapse to the same value.
256	     *
257	     * @param normalizedTelephone the submitted, already-normalized telephone digits
258	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
259	     *                                     same normalized telephone
260	     */
261	    /**
262	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
263	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
264	     * the parts may contain whitespace or a second {@code @}.
265	     */
266	    private static final Pattern EMAIL_PATTERN =
267	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
268	
269	    /**
270	     * Normalizes the submitted email when present: the value is trimmed, required to be a
271	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
272	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
273	     *
274	     * @param ownerFieldsDto the submitted owner fields
275	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
276	     */
277	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
278	        String email = ownerFieldsDto.getEmail();
279	        if (email == null) {
280	            return;
281	        }
282	        String trimmed = email.strip();
283	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
284	            throw new InvalidEmailException(email);
285	        }
286	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
287	    }
288	
289	    /**
290	     * Defaults the registration date on create: when the client does not supply a
291	     * {@code registrationDate}, it is set to the server's current date so it is persisted
292	     * and echoed back in ISO 'YYYY-MM-DD' format. A supplied value is left untouched.
293	     *
294	     * @param ownerFieldsDto the submitted owner fields
295	     */
296	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
297	        if (ownerFieldsDto.getRegistrationDate() == null) {
298	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
299	        }
300	    }
301	
302	    private void rejectDuplicateTelephone(String normalizedTelephone) {
303	        boolean duplicate = this.clinicService.findAllOwners().stream()
304	            .map(Owner::getTelephone)
305	            .filter(telephone -> telephone != null)
306	            .map(telephone -> telephone.replaceAll("\\D", ""))
307	            .anyMatch(normalizedTelephone::equals);
308	        if (duplicate) {
309	            throw new DuplicateTelephoneException(normalizedTelephone);
310	        }
311	    }
312	
313	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
314	    @Override
315	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
316	        Owner owner = this.clinicService.findOwnerById(ownerId);
317	        if (owner != null) {
318	            Pet pet = owner.getPet(petId);
319	            if (pet != null) {
320	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
321	            }
322	        }
